function numTrees(n) {
  if (n <= 1) return 1;
  let total = 0;
  for (let r = 1; r <= n; r++) total += numTrees(r - 1) * numTrees(n - r);   // left shapes x right shapes
  return total;
}

def num_trees(n):
    if n <= 1:
        return 1
    total = 0
    for r in range(1, n + 1):
        total += num_trees(r - 1) * num_trees(n - r)   # left shapes x right shapes
    return total

int numTrees(int n) {
    if (n <= 1) return 1;
