function numTrees(n) {
  const G = new Array(n + 1).fill(0);
  G[0] = 1;
  G[1] = 1;
  for (let k = 2; k <= n; k++) {           // k values
    for (let r = 1; r <= k; r++) G[k] += G[r - 1] * G[k - r];
  }
  return G[n];
}

int numTrees(int n) {
    long[] G = new long[n + 2];
    G[0] = 1;
    G[1] = 1;
    for (int k = 2; k <= n; k++) {                   // k values
        for (int r = 1; r <= k; r++) G[k] += G[r - 1] * G[k - r];
    }
    return (int) G[n];
}

